'use strict';
// Standalone offline prototype: no Redis, TMDB, Vercel or production imports.
const FIELDS=['title','originalTitle','releaseDate','posterPath','voteAverage','runtimeMinutes','genres','overview','directors','cast','collectionId','seasonCount','episodeCount','status'];
const MANUAL=['note','shortIntro','order','section'];
const LIMIT=4000;
function key(type,id){if(!['movie','tv'].includes(type)||!Number.isSafeInteger(Number(id))||Number(id)<1)throw Error('invalid identity');return type+':'+Number(id)}
function clean(input){const out={};for(const f of FIELDS){if(Object.prototype.hasOwnProperty.call(input,f)){const v=input[f];if(typeof v==='string')out[f]=v.slice(0,LIMIT);else if(typeof v==='number'&&Number.isFinite(v))out[f]=v;else if(Array.isArray(v))out[f]=v.slice(0,f==='cast'?8:20).map(x=>typeof x==='string'?x.slice(0,200):x).filter(x=>typeof x==='string'||typeof x==='number');else if(v===null)out[f]=null;}}return out}
function bytes(x){return Buffer.byteLength(JSON.stringify(x),'utf8')}
function store(io){const records=new Map();const errorLog=[];function record(type,id){const r=records.get(key(type,id));if(!r)throw Error('not found');return r}
function register(type,id,raw){const k=key(type,id);if(records.has(k))return false;records.set(k,{type,id:Number(id),fields:clean(raw),confirmed:false,lockedFields:[],memberships:[],pageExtras:{},errors:[],createdAt:new Date().toISOString(),ratingCheckedAt:null});return true}
function edit(type,id,patch){const r=record(type,id);if(r.confirmed)throw Error('confirmed record locked');Object.assign(r.fields,clean(patch));for(const f of Object.keys(clean(patch)))if(!r.lockedFields.includes(f))r.lockedFields.push(f)}
function confirm(type,id){const r=record(type,id);if(r.errors.some(e=>e.status==='open'))throw Error('unresolved errors');r.confirmed=true;r.lockedFields=[...new Set([...r.lockedFields,...Object.keys(r.fields)])]}
function automatic(type,id,raw){const r=record(type,id);const next=clean(raw);for(const [f,v] of Object.entries(next)){if(!r.confirmed&&!r.lockedFields.includes(f))r.fields[f]=v}}
function rating(type,id,value,date){const r=record(type,id);const t=Date.parse(date);if(!Number.isFinite(t))throw Error('invalid date');const prev=r.ratingCheckedAt?Date.parse(r.ratingCheckedAt):0;if(prev&&t-prev<365*86400000)return false;if(typeof value!=='number'||!Number.isFinite(value))throw Error('invalid rating');r.fields.voteAverage=value;r.ratingCheckedAt=date;return true}
function member(type,id,kind,scope,extra={}){const r=record(type,id);if(!['watchOrder','feature'].includes(kind)||typeof scope!=='string'||!scope.trim()||scope.length>80)throw Error('invalid membership');const mk=kind+':'+scope;if(!r.memberships.some(m=>m.kind+':'+m.scope===mk))r.memberships.push({kind,scope});const safe={};for(const f of MANUAL)if(Object.prototype.hasOwnProperty.call(extra,f)){const v=extra[f];if(typeof v==='string')safe[f]=v.slice(0,1000);else if(f==='order'&&Number.isSafeInteger(v))safe[f]=v}if(Object.keys(safe).length)r.pageExtras[mk]={...(r.pageExtras[mk]||{}),...safe}}
function error(type,id,message){const r=record(type,id);const eid=errorLog.length+1;const e={eid,message:String(message).slice(0,500),status:'open'};r.errors.push(e);errorLog.push({key:key(type,id),...e});return eid}
function resolve(type,id,eid){const r=record(type,id);const e=r.errors.find(e=>e.eid===eid);if(!e)throw Error('error not found');e.status='resolved';const log=errorLog.find(e=>e.eid===eid);log.status='resolved'}
function pending(){return [...records.values()].filter(r=>!r.confirmed).map(r=>({key:key(r.type,r.id),errors:r.errors.filter(e=>e.status==='open').length}))}
function errors(){return errorLog.map(e=>({...e}))}
function display(type,id){const r=record(type,id);return {id:r.id,type:r.type,...r.fields,confirmed:r.confirmed,memberships:r.memberships}}
function audit(){const list=[...records.values()];const allowed=['type','id','fields','confirmed','lockedFields','memberships','pageExtras','errors','createdAt','ratingCheckedAt'];return {count:list.length,totalBytes:bytes(list),items:list.map(r=>({key:key(r.type,r.id),bytes:bytes(r),unexpected:Object.keys(r).filter(k=>!allowed.includes(k))})),duplicates:list.length-new Set(list.map(r=>key(r.type,r.id))).size}}
function save(){const data=JSON.stringify({records:[...records.values()],errorLog});if(io&&io.write)io.write(data);return data}
function load(data){const raw=JSON.parse(data||(io&&io.read&&io.read())||'{}');records.clear();errorLog.length=0;for(const x of raw.records||[]){const k=key(x.type,x.id);if(records.has(k))throw Error('duplicate');const r={type:x.type,id:Number(x.id),fields:clean(x.fields||{}),confirmed:!!x.confirmed,lockedFields:(x.lockedFields||[]).filter(f=>FIELDS.includes(f)),memberships:[],pageExtras:{},errors:[],createdAt:x.createdAt||null,ratingCheckedAt:x.ratingCheckedAt||null};for(const m of x.memberships||[])memberAfterLoad(r,m);for(const [mk,extra] of Object.entries(x.pageExtras||{})){if(r.memberships.some(m=>m.kind+':'+m.scope===mk)){const safe={};for(const f of MANUAL)if(typeof extra[f]==='string')safe[f]=extra[f].slice(0,1000);else if(f==='order'&&Number.isSafeInteger(extra[f]))safe[f]=extra[f];r.pageExtras[mk]=safe}}r.errors=(x.errors||[]).filter(e=>Number.isInteger(e.eid)&&['open','resolved'].includes(e.status)).map(e=>({eid:e.eid,message:String(e.message).slice(0,500),status:e.status}));records.set(k,r)}for(const e of raw.errorLog||[])if(records.has(e.key))errorLog.push({key:e.key,eid:e.eid,message:String(e.message).slice(0,500),status:e.status})}
function memberAfterLoad(r,m){if(['watchOrder','feature'].includes(m.kind)&&typeof m.scope==='string'&&m.scope.length<=80&&!r.memberships.some(x=>x.kind===m.kind&&x.scope===m.scope))r.memberships.push({kind:m.kind,scope:m.scope})}
return {register,edit,confirm,automatic,rating,member,error,resolve,pending,errors,display,audit,save,load}}
module.exports={store,key,clean};
